        address lender;
    }

    constructor() {
        loans.push(
            Loan(100, msg.sender)
        );
    }

    function repay (uint256 loanID) external returns (address) {
        Loan storage loan = loans[loanID];

        delete loans[loanID];

        return loan.lender;
    }
}
```
Steps:
1) Deploy ```Cooler```.
2) Call ```repay``` with ```loanID``` of 0.
3) Observe the returned value (should be ```0x0```).

